const i = $json ?? {};
const clean = v => (v === undefined || v === null) ? null : (String(v).trim() || null);
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const base = (clean(i.booking_base_url) || '').replace(/\/$/, '');
const contactId = clean(i.contact_id);
const serviceId = clean(i.service_id);
const startAt = clean(i.start_at);

if (!base) throw new Error('booking_base_url no configurado (nodo Config)');
if (!serviceId || !uuid.test(serviceId)) throw new Error('service_id no es un UUID válido');
if (!contactId || !uuid.test(contactId)) throw new Error('contact_id no es un UUID válido');
if (!startAt || Number.isNaN(Date.parse(startAt))) throw new Error(`start_at no es una fecha válida: ${startAt}`);

const src = clean(i.source);
const body = {
  service_id: serviceId,
  start_at: startAt,
  contact_id: contactId,
  source: ['ai', 'manual', 'system'].includes(src) ? src : 'ai',
};
const opt = {
  title: clean(i.title),
  notes: clean(i.notes),
  primary_resource_id: clean(i.primary_resource_id),
  location_id: clean(i.location_id),
  calendar_id: clean(i.calendar_id),
  idempotency_key: clean(i.idempotency_key),
};
for (const [k, v] of Object.entries(opt)) if (v) body[k] = v;

return [{ json: { _url: base + '/api/book', _body: body } }];

const r = $json ?? {};
const status = r.statusCode ?? 0;
const body = (r.body ?? r) || {};

if (body.ok === true) {
  return [{ json: {
    status: 'created',
    appointment: {
      id: body.appointment_id,
      status: body.status,
      start_at: body.start_at,
      end_at: body.end_at,
      primary_resource_id: body.primary_resource_id,
      participant_resource_ids: body.participant_resource_ids ?? [],
    },
    idempotent: body.idempotent === true,
  } }];
}

return [{ json: {
  status: 'error',
  error: body.error || ('http_' + status),
  message: body.detail || 'El Booking API rechazó la creación',
} }];
